(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20 + Math.sin(x*0.013+t*0.22)*15;
  const w2x = Math.sin((x+w1x)*0.02+t*0.3)*10 + Math.cos((y+w1y)*0.018-t*0.25)*8;
  const w2y = Math.cos((y+w1y)*0.02-t*0.28)*10 + Math.sin((x+w1x)*0.016+t*0.32)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.07,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.09,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.05,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.11,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.06,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.08,1.9,0.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.13,1.3,0.6],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*50,0.04,2.8,1.3],
    [200+Math.sin(t*0.7+6)*90,220+Math.cos(t*0.3+3)*60,0.1,1.6,0.85]
  ];
  let act=0,inh=0,act2=0,inh2=0,minD=999,secD=999;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp)*amp;
    inh+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    act2+=Math.sin(d*f*1.8-t*sp*1.3+2)*amp*0.5;
    inh2+=Math.sin(d*f*1.3+t*sp*0.9+0.8)*amp*0.5;
    const vd=Math.sqrt((sx-sX*0.3+cx*0.7)**2+(sy-sY*0.3+cy*0.7)**2);
    if(vd<minD){secD=minD;minD=vd}else if(vd<secD){secD=vd}
  }
  const n=src.length;
  act/=n;inh/=n;act2/=n;inh2/=n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3
    +Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t*0.5)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35
    +Math.sin(dist*0.08-ang*2+t*0.8)*0.3;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((act2-inh2*0.6+rd1*0.8+spiral*0.5)*2.0);
  const coupled=Math.tanh((rd1*0.6+rd2*0.4)*2.5);
  const cellEdge=Math.tanh((secD-minD)*0.15-0.5)*0.4;
  const v=(coupled*0.7+cellEdge*0.3)*0.5+0.5;
  const pal=[
    [6,14,62],[10,52,92],[14,98,108],[18,148,128],[42,172,108],
    [180,188,52],[218,148,48],[208,98,58],[178,52,58],[118,28,62],
    [52,16,58],[6,14,62]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const bright=(0.85+Math.sin(coupled*Math.PI)*0.15)*(Math.abs(coupled)>0.65?1.12:Math.abs(coupled)>0.3?1.0:0.92);
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*bright)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*bright)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*bright)|0
  ];
}
